//! The stat table (C113, C106; K6 in `decisions/search.md`; step 2 of
//! `search/TRADE-PLAN.md`): the trade site's stat ids in its six hash
//! categories, to the text the site displays for each — the vocabulary
//! the translation writes a `line("…")` from (step 4), and nothing else
//! reads (C90: a stat id exists only at the trade boundary).
//!
//! # As built
//!
//! - **The table is `reference/trade-stats-v1.toml`** beside this crate,
//!   compiled in by `include_str!` and parsed once, on first use
//!   ([`table`]); generated by `tools/trade-stats-table.py` from the
//!   owner's dated capture of the site's vocabulary
//!   (`search/trade-query/data/stats-2026-09-12.json`, its sha256 pinned
//!   in the script), reviewed as a diff at each new capture, pinned by
//!   `tests/trade_stats.rs`. It is *convention* under C106 — the site's own
//!   words for its ids — and the file's header and the script's docstring
//!   carry the rules a reviewer reads.
//! - **A row is an id, the categories that carry it, and its texts.** The
//!   id is keyed without its category because its texts are the same
//!   under every category that carries it: measured at generation over
//!   the 2,499 ids the capture lists under more than one category, and the
//!   script stops where it is not, so the shape cannot hide a capture that
//!   breaks it. An id may carry several texts — the site lists 172 ids
//!   twice in one category, a map's own wording beside the atlas's `your
//!   Maps` — and the row keeps them all in the capture's order; which one a
//!   clause matches is the translation's, never this table's.
//! - **The loader checks what a reviewer would**: the version this build
//!   expects ([`STAT_TABLE_VERSION`], the capture's date), a source named,
//!   every id once and an id ([`is_id`]: what every id of the capture is),
//!   every row under at least one category, each one of the six and none
//!   twice, every text non-empty and none twice under one id, and each of
//!   the six categories carrying some id. A table that fails is a build
//!   defect surfaced as [`StatTableError`] to whoever asks, never a
//!   partial table; the corpus never loads it, so an ordinary search
//!   neither pays for it nor fails by it.
//! - **The version is the basis's** (C98) from the step whose answer reads
//!   the table (step 4): only an answer that used it cites it.

use std::collections::{HashMap, HashSet};
use std::sync::LazyLock;

use serde::Deserialize;

/// The table this build ships, verbatim (the generated file).
pub const STAT_TABLE_TOML: &str = include_str!("../../reference/trade-stats-v1.toml");

/// The table version this build expects and every basis that reads it
/// cites: the capture's date. A file stamped otherwise is a build defect.
pub const STAT_TABLE_VERSION: &str = "2026-09-12";

/// The site's hash categories, the six the catalogue lands as a line
/// (`stat.<category>` in `reference/trade-catalogue-v1.toml`), in the
/// capture's order.
pub const HASH_CATEGORIES: [&str; 6] = [
    "explicit",
    "implicit",
    "fractured",
    "enchant",
    "scourge",
    "crafted",
];

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct File {
    version: String,
    source: String,
    #[allow(dead_code)]
    generated_by: String,
    #[serde(rename = "stat", default)]
    stats: Vec<Row>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Row {
    id: String,
    #[serde(rename = "in")]
    categories: Vec<String>,
    texts: Vec<String>,
}

/// One id as the site displays it.
#[derive(Debug)]
struct Stat {
    /// The categories carrying it, as bits over [`HASH_CATEGORIES`].
    categories: u8,
    texts: Vec<String>,
}

/// The parsed, checked table. Read-only; one per build.
#[derive(Debug)]
pub struct StatTable {
    version: String,
    source: String,
    by_id: HashMap<String, Stat>,
    /// The ids each text names, by category: (category bit, text) to ids,
    /// in the file's order.
    by_text: HashMap<(u8, String), Vec<String>>,
}

/// Why a table text is not a table. Every arm names the offending row so a
/// reviewer can fix the file, not the loader.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum StatTableError {
    Parse(String),
    Version {
        found: String,
        expected: &'static str,
    },
    NoSource,
    NoStat,
    BadId(String),
    DuplicateId(String),
    NoCategory {
        id: String,
    },
    UnknownCategory {
        id: String,
        category: String,
    },
    DuplicateCategory {
        id: String,
        category: String,
    },
    NoText {
        id: String,
    },
    EmptyText {
        id: String,
    },
    DuplicateText {
        id: String,
        text: String,
    },
    EmptyCategory(&'static str),
}

impl std::fmt::Display for StatTableError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            StatTableError::Parse(e) => write!(f, "the stat table does not parse: {e}"),
            StatTableError::Version { found, expected } => write!(
                f,
                "the stat table is version {found}; this build reads version {expected}"
            ),
            StatTableError::NoSource => write!(f, "the stat table names no source"),
            StatTableError::NoStat => write!(f, "the stat table has no stat"),
            StatTableError::BadId(id) => write!(
                f,
                "the stat table has the id {id:?}, which is not ASCII letters, digits, `_` and `|`"
            ),
            StatTableError::DuplicateId(id) => {
                write!(f, "the stat table names the id {id:?} twice")
            }
            StatTableError::NoCategory { id } => {
                write!(f, "the stat table puts {id:?} under no category")
            }
            StatTableError::UnknownCategory { id, category } => write!(
                f,
                "the stat table puts {id:?} under {category:?}, which is no hash category"
            ),
            StatTableError::DuplicateCategory { id, category } => {
                write!(f, "the stat table puts {id:?} under {category:?} twice")
            }
            StatTableError::NoText { id } => write!(f, "the stat table gives {id:?} no text"),
            StatTableError::EmptyText { id } => {
                write!(f, "the stat table gives {id:?} an empty text")
            }
            StatTableError::DuplicateText { id, text } => {
                write!(f, "the stat table gives {id:?} the text {text:?} twice")
            }
            StatTableError::EmptyCategory(category) => {
                write!(f, "the stat table puts no id under {category:?}")
            }
        }
    }
}

impl std::error::Error for StatTableError {}

static TABLE: LazyLock<Result<StatTable, StatTableError>> =
    LazyLock::new(|| StatTable::parse(STAT_TABLE_TOML));

/// Whether a word is a stat id as the table keys it: one ASCII letter,
/// digit, `_` or `|` or more, which every id of the capture is (10,303 of
/// 10,303, measured at step 2's review). Stated as what an id is, not as
/// what it may not hold, so no category prefix, whitespace or control
/// character passes by being one the rule forgot.
pub fn is_id(word: &str) -> bool {
    !word.is_empty()
        && word
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'|')
}

/// The shipped table, parsed and checked once.
pub fn table() -> Result<&'static StatTable, &'static StatTableError> {
    TABLE.as_ref()
}

impl StatTable {
    /// Parse and check a table text. The shipped file goes through
    /// [`table`]; this is the same path over any text, for the tests that
    /// pin what the loader refuses.
    pub fn parse(text: &str) -> Result<StatTable, StatTableError> {
        let file: File = toml::from_str(text).map_err(|e| StatTableError::Parse(e.to_string()))?;
        if file.version != STAT_TABLE_VERSION {
            return Err(StatTableError::Version {
                found: file.version,
                expected: STAT_TABLE_VERSION,
            });
        }
        if file.source.trim().is_empty() {
            return Err(StatTableError::NoSource);
        }
        if file.stats.is_empty() {
            return Err(StatTableError::NoStat);
        }
        let mut by_id: HashMap<String, Stat> = HashMap::with_capacity(file.stats.len());
        let mut by_text: HashMap<(u8, String), Vec<String>> = HashMap::new();
        let mut carried = 0u8;
        for row in file.stats {
            if !is_id(&row.id) {
                return Err(StatTableError::BadId(row.id));
            }
            if by_id.contains_key(&row.id) {
                return Err(StatTableError::DuplicateId(row.id));
            }
            if row.categories.is_empty() {
                return Err(StatTableError::NoCategory { id: row.id });
            }
            let mut categories = 0u8;
            for category in row.categories {
                let Some(at) = HASH_CATEGORIES.iter().position(|c| *c == category) else {
                    return Err(StatTableError::UnknownCategory {
                        id: row.id,
                        category,
                    });
                };
                if categories & (1 << at) != 0 {
                    return Err(StatTableError::DuplicateCategory {
                        id: row.id,
                        category,
                    });
                }
                categories |= 1 << at;
            }
            if row.texts.is_empty() {
                return Err(StatTableError::NoText { id: row.id });
            }
            let mut seen = HashSet::with_capacity(row.texts.len());
            for text in &row.texts {
                if text.trim().is_empty() {
                    return Err(StatTableError::EmptyText { id: row.id });
                }
                if !seen.insert(text.as_str()) {
                    return Err(StatTableError::DuplicateText {
                        id: row.id.clone(),
                        text: text.clone(),
                    });
                }
            }
            carried |= categories;
            for at in 0..HASH_CATEGORIES.len() {
                if categories & (1 << at) != 0 {
                    for text in &row.texts {
                        by_text
                            .entry((at as u8, text.clone()))
                            .or_default()
                            .push(row.id.clone());
                    }
                }
            }
            by_id.insert(
                row.id,
                Stat {
                    categories,
                    texts: row.texts,
                },
            );
        }
        if let Some(at) = (0..HASH_CATEGORIES.len()).find(|at| carried & (1 << at) == 0) {
            return Err(StatTableError::EmptyCategory(HASH_CATEGORIES[at]));
        }
        Ok(StatTable {
            version: file.version,
            source: file.source,
            by_id,
            by_text,
        })
    }

    /// The version every basis that read the table cites.
    pub fn version(&self) -> &str {
        &self.version
    }

    /// The table-level source, verbatim.
    pub fn source(&self) -> &str {
        &self.source
    }

    /// How many ids the table carries.
    pub fn ids(&self) -> usize {
        self.by_id.len()
    }

    /// The texts the site displays for a stat as its query names it,
    /// `<category>.<id>` — `explicit.stat_3299347043` — in the capture's
    /// order; none where the category is no hash category or does not
    /// carry the id (the catalogue's `stat.unknown`, step 4).
    pub fn texts(&self, stat: &str) -> Option<&[String]> {
        let (category, id) = stat.split_once('.')?;
        let at = HASH_CATEGORIES.iter().position(|c| *c == category)?;
        let found = self.by_id.get(id)?;
        (found.categories & (1 << at) != 0).then_some(found.texts.as_slice())
    }

    /// The ids the site displays a text as under one hash category, read
    /// exactly, in the file's order: two or more is the text S66 names
    /// (the catalogue's `stat.text.collision`); none where the category is
    /// no hash category.
    pub fn ids_of(&self, category: &str, text: &str) -> &[String] {
        HASH_CATEGORIES
            .iter()
            .position(|c| *c == category)
            .and_then(|at| self.by_text.get(&(at as u8, text.to_string())))
            .map_or(&[], Vec::as_slice)
    }

    /// The hash categories that carry an id, in the capture's order.
    pub fn categories(&self, id: &str) -> Vec<&'static str> {
        let Some(found) = self.by_id.get(id) else {
            return Vec::new();
        };
        HASH_CATEGORIES
            .iter()
            .enumerate()
            .filter(|(at, _)| found.categories & (1 << at) != 0)
            .map(|(_, c)| *c)
            .collect()
    }
}
